using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");
Console.WriteLine($"  Properties: {personInfo.Properties.Count}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
//    Use a resolver that only knows about Person, not about UnknownRecord.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new LimitedResolver())
};

bool found = limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person):  found={found}, info={info?.Type.Name}");

bool notFound = limitedOptions.TryGetTypeInfo(typeof(UnknownRecord), out JsonTypeInfo? missing);
Console.WriteLine($"TryGetTypeInfo(UnknownRecord): found={notFound}, info={missing?.Type.Name ?? "(null)"}");

// Types used in the demo
public record Person(string Name, int Age);
public record UnknownRecord(string Data);

// A resolver that only provides metadata for Person
file class LimitedResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signals "not available"
    }
}
